export const ROUTE_KEYS = Object.keys(ROUTE_CONTRACTS) as readonly string[];

/** Resolve a contract by "METHOD /path" (also tolerates lowercase method). */
export function routeContract(key: string): RouteContract | undefined {
  const sp = key.indexOf(' ');
  if (sp <= 0) return undefined;
  return ROUTE_CONTRACTS[`${key.slice(0, sp).toUpperCase()}${key.slice(sp)}`];
}
